using EventModel.Domain;
using EventModel.Domain.OrderAggregate;
using Xunit;

namespace EventModel.Domain.Tests;

/// Slice "place-order" (state-change): Checkout Page -> PlaceOrder -> OrderPlaced
public class PlaceOrderSliceTests
{
    private static readonly DateTimeOffset Now = new(2026, 8, 4, 12, 0, 0, TimeSpan.Zero);

    [Fact]
    public void Given_no_history_When_PlaceOrder_Then_OrderPlaced()
    {
        var state = OrderState.From(Array.Empty<object>());
        var command = new PlaceOrder(
            OrderId: Guid.Parse("00000000-0000-0000-0000-000000000001"),
            CustomerId: Guid.Parse("00000000-0000-0000-0000-000000000002"),
            TotalAmount: 100m,
            Currency: "sample-currency");

        var events = OrderDecider.Decide(state, command, Now);

        var e = Assert.IsType<OrderPlaced>(Assert.Single(events));
        Assert.Equal(command.OrderId, e.OrderId);
        Assert.Equal(command.CustomerId, e.CustomerId);
        Assert.Equal(command.TotalAmount, e.TotalAmount);
        Assert.Equal(command.Currency, e.Currency);
        Assert.Equal(Now, e.PlacedAt);
    }

    [Fact]
    public void Given_no_history_When_PlaceOrder_violates_EmptyOrder_Then_rejected()
    {
        var state = OrderState.From(Array.Empty<object>());
        var command = new PlaceOrder(
            OrderId: Guid.Parse("00000000-0000-0000-0000-000000000001"),
            CustomerId: Guid.Parse("00000000-0000-0000-0000-000000000002"),
            TotalAmount: 0m,
            Currency: "sample-currency");

        var ex = Assert.Throws<RejectionException>(() => OrderDecider.Decide(state, command, Now));

        Assert.Equal("EmptyOrder", ex.Rule);
    }

    [Fact]
    public void OrderPlaced_folds_into_state()
    {
        var state = OrderState.From(Array.Empty<object>());
        var command = new PlaceOrder(
            OrderId: Guid.Parse("00000000-0000-0000-0000-000000000001"),
            CustomerId: Guid.Parse("00000000-0000-0000-0000-000000000002"),
            TotalAmount: 100m,
            Currency: "sample-currency");

        var next = OrderState.From(OrderDecider.Decide(state, command, Now));

        Assert.True(next.Exists);
    }
}
